mapper.select:
SELECT id, spu_id, sku_code, barcode, spec_name, spec_values, sale_unit, product_type, market_price, status, is_default, sort_order, version, deleted, created_at, updated_at, created_by, updated_by FROM product_sku WHERE deleted = FALSE AND spu_id IN
#{spuId}
ORDER BY spu_id, sort_order, id
